-- ═════════════════════════════════════════════════════════════
-- Vote2027 — banque de questions du Quiz (1650 questions, 11 thèmes)
-- Source : quiz_vote27_complete.xlsx (Drive), relu et complété manuellement
-- (bonne réponse + 3 distracteurs par question). À exécuter après
-- supabase/schema.sql. Idempotent : chaque instruction peut être rejouée.
--
-- statut : 'active' (utilisable), 'a_verifier' / 'doublon' / 'retiree'
-- (exclues de get_daily_quiz, conservées pour trace/relecture).
-- ═════════════════════════════════════════════════════════════

create table if not exists public.quiz_themes (
  slug             text primary key,
  label            text not null,
  ordre            integer not null,
  is_time_sensitive boolean not null default false
);

alter table public.quiz_themes enable row level security;

drop policy if exists "quiz_themes: lecture publique" on public.quiz_themes;
create policy "quiz_themes: lecture publique" on public.quiz_themes
  for select to anon, authenticated using (true);

insert into public.quiz_themes (slug, label, ordre, is_time_sensitive) values

  ('constitution-et-institutions', 'La Constitution de 1958 et les institutions de la Vème République', 1, false),
  ('pouvoir-executif', 'Le pouvoir exécutif (Président, gouvernement, Premier ministre)', 2, false),
  ('pouvoir-legislatif', 'Le pouvoir législatif (Assemblée nationale, Sénat, élaboration de la loi)', 3, false),
  ('elections', 'Le système électoral et les élections (présidentielle, législatives, référendums)', 4, false),
  ('presidents-de-la-ve', 'Les présidents de la Vème République', 5, false),
  ('partis-politiques', 'Les partis politiques et le paysage politique français', 6, false),
  ('citoyennete-et-droits', 'La citoyenneté et les droits civiques (droits fondamentaux, laïcité, nationalité)', 7, false),
  ('justice', 'La justice et les institutions judiciaires', 8, false),
  ('france-et-union-europeenne', 'La France et l''Union européenne (institutions, traités, souveraineté)', 9, false),
  ('grands-evenements-et-reformes', 'Grands événements et réformes politiques de la Vème République', 10, false),
  ('candidats-2027', 'Candidats 2027 (panorama des programmes — données du 16 septembre 2026)', 11, true)

on conflict (slug) do update set label = excluded.label, ordre = excluded.ordre, is_time_sensitive = excluded.is_time_sensitive;

create table if not exists public.quiz_questions (
  code         text primary key,
  theme_slug   text not null references public.quiz_themes (slug),
  ordre        integer not null,
  question     text not null,
  bonne_reponse text not null,
  mauvaise_1   text not null,
  mauvaise_2   text not null,
  mauvaise_3   text not null,
  explication  text,
  statut       text not null default 'active' check (statut in ('active', 'a_verifier', 'doublon', 'retiree')),
  created_at   timestamptz not null default now()
);

create index if not exists quiz_questions_theme_idx on public.quiz_questions (theme_slug);
create index if not exists quiz_questions_statut_idx on public.quiz_questions (statut);

alter table public.quiz_questions enable row level security;

drop policy if exists "quiz_questions: lecture publique active" on public.quiz_questions;
create policy "quiz_questions: lecture publique active" on public.quiz_questions
  for select to anon, authenticated using (statut = 'active');

