on conflict (code) do update set
  theme_slug = excluded.theme_slug,
  ordre = excluded.ordre,
  question = excluded.question,
  bonne_reponse = excluded.bonne_reponse,
  mauvaise_1 = excluded.mauvaise_1,
  mauvaise_2 = excluded.mauvaise_2,
  mauvaise_3 = excluded.mauvaise_3,
  explication = excluded.explication,
  statut = excluded.statut;


-- ─────────────────────────────────────────────────────────────
-- Quiz du jour — 5 questions actives, tirées de façon déterministe par
-- date (même quiz pour tout le monde un jour donné, ce qui rend le
-- classement comparable). L'ordre des 4 réponses est mélangé côté client.
-- ─────────────────────────────────────────────────────────────
create or replace function public.get_daily_quiz(p_date date default (now() at time zone 'Europe/Paris')::date)
returns table (
  code text,
  theme_label text,
  question text,
  bonne_reponse text,
  mauvaise_1 text,
  mauvaise_2 text,
  mauvaise_3 text,
  explication text
)
language sql
stable
security definer set search_path = public
as $$
  select q.code, t.label, q.question, q.bonne_reponse, q.mauvaise_1, q.mauvaise_2, q.mauvaise_3, q.explication
  from public.quiz_questions q
  join public.quiz_themes t on t.slug = q.theme_slug
  where q.statut = 'active'
  order by md5(q.code || p_date::text)
  limit 5;
$$;

grant execute on function public.get_daily_quiz(date) to authenticated, anon;

-- Records which 5 questions were asked that day, for a future "revoir mes
-- réponses" screen — additive, existing rows keep question_codes = null.
alter table public.quiz_attempts add column if not exists question_codes text[];
